package com.notessync.app.sync

import com.notessync.app.sync.core.*
import com.notessync.app.sync.crypto.PairingHandshake
import com.notessync.app.sync.protocol.*
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test
import java.io.*
import java.net.ServerSocket
import java.net.Socket
import java.util.UUID
import java.util.concurrent.*
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicReference
import kotlin.concurrent.thread

/** Real encrypted loopback, generated bytes and counting sinks: no phone/memory benchmark. */
class StreamingSessionTest {
    private val size = 3L * 1024 * 1024 + 17
    private class Pattern(private val size: Long, private val failAt: Long = Long.MAX_VALUE,
        val largestRead: AtomicInteger = AtomicInteger(), val closed: AtomicBoolean = AtomicBoolean()) : InputStream() {
        private var position = 0L
        override fun read(): Int {
            if (position >= failAt) throw IOException("Injected interrupted source")
            return if (position >= size) -1 else (position++ % 251).toInt()
        }
        override fun read(bytes: ByteArray, offset: Int, length: Int): Int {
            largestRead.accumulateAndGet(length, ::maxOf)
            if (position >= failAt) throw IOException("Injected interrupted source")
            if (position >= size) return -1
            val count = minOf(length.toLong(), size - position, failAt - position).toInt()
            for (i in 0 until count) bytes[offset + i] = ((position + i) % 251).toByte()
            position += count
            return count
        }
        override fun close() { closed.set(true) }
    }
    private class Device(val meta: AttachmentDto, var ownsFile: Boolean, val failAt: Long = Long.MAX_VALUE) : StreamingSyncDataSource {
        val notes = mutableMapOf<String, NoteDto>()
        val opened = AtomicBoolean(); val sourceClosed = AtomicBoolean(); val sinkClosed = AtomicBoolean()
        val largestRead = AtomicInteger(); val largestWrite = AtomicInteger(); var written = 0L; var acknowledgements = 0
        override suspend fun ensureSyncIds() = Unit
        override suspend fun getChangesSince(since: Long) = ChangeSet(notes = notes.values.toList())
        override suspend fun applyChanges(changes: ChangeSet): ApplyStats {
            notes.putAll(changes.notes.associateBy { it.syncId })
            return ApplyStats(appliedNotes = changes.notes.size,
                missingAttachments = changes.notes.flatMap { it.attachments }.filter { !ownsFile })
        }
        override suspend fun hasAttachmentBytes(attachmentSyncId: String) = ownsFile
        override suspend fun readAttachmentBytes(attachmentSyncId: String): ByteArray? = error("Array read must not run")
        override suspend fun writeAttachmentBytes(meta: AttachmentDto, data: ByteArray) = error("Array write must not run")
        override suspend fun markSynced(changeSet: ChangeSet) { acknowledgements++ }
        override suspend fun openAttachment(attachmentSyncId: String): SyncAttachmentSource? {
            if (!ownsFile) return null
            opened.set(true)
            return SyncAttachmentSource(meta.sizeBytes, Pattern(meta.sizeBytes, failAt, largestRead, sourceClosed))
        }
        override suspend fun receiveAttachment(meta: AttachmentDto): SyncAttachmentSink {
            val output = object : OutputStream() {
                override fun write(value: Int) { assertEquals((written % 251).toInt(), value and 255); written++ }
                override fun write(bytes: ByteArray, offset: Int, length: Int) {
                    largestWrite.accumulateAndGet(length, ::maxOf)
                    for (i in 0 until length) assertEquals(((written + i) % 251).toInt(), bytes[offset + i].toInt() and 255)
                    written += length
                }
                override fun close() { sinkClosed.set(true) }
            }
            return VerifiedAttachmentSink(meta, output, publish = { ownsFile = true })
        }
    }
    private fun devices(failAt: Long = Long.MAX_VALUE): Pair<Device, Device> {
        val meta = AttachmentDto(UUID.randomUUID().toString(), "stream-note", "audio/mp4", size, Hashing.sha256Hex(Pattern(size)))
        return Device(meta, true, failAt).apply {
            notes[meta.noteSyncId] = NoteDto(meta.noteSyncId, "Stream", "Body", false, false, 1, 2, attachments = listOf(meta))
        } to Device(meta, false)
    }
    private fun exchange(a: Device, b: Device): Pair<Result<SyncResult>, Result<SyncResult>> {
        val server = ServerSocket(0); server.soTimeout = 5_000
        val host = AtomicReference<Socket>(); val result = CompletableFuture<Result<SyncResult>>()
        val worker = thread(name = "stream-loopback") {
            try {
                server.accept().use { socket ->
                    host.set(socket); socket.soTimeout = 5_000
                    result.complete(runCatching { runBlocking {
                        val crypto = PairingHandshake.establish(socket.getInputStream(), socket.getOutputStream(), "ce".repeat(32), client = false)
                        SyncSession(FrameTransport(socket.getInputStream(), socket.getOutputStream(), crypto), a, "server", "Server", { 0L }).runAsServer()
                    } })
                }
            } catch (error: Throwable) { result.complete(Result.failure(error)) }
        }
        try {
            val client = Socket("127.0.0.1", server.localPort).use { socket ->
                socket.soTimeout = 5_000
                runCatching { runBlocking {
                    val crypto = PairingHandshake.establish(socket.getInputStream(), socket.getOutputStream(), "ce".repeat(32), client = true)
                    SyncSession(FrameTransport(socket.getInputStream(), socket.getOutputStream(), crypto), b, "client", "Client", { 0L }).runAsClient()
                } }
            }
            return result.get(10, TimeUnit.SECONDS) to client
        } finally { server.close(); host.get()?.close(); worker.join(5_000); assertFalse(worker.isAlive) }
    }
    @Test fun `encrypted transfer streams chunks without using either byte array API`() {
        val (a, b) = devices(); val (server, client) = exchange(a, b)
        assertTrue(server.toString(), server.isSuccess); assertTrue(client.toString(), client.isSuccess)
        assertTrue(a.opened.get()); assertTrue(a.sourceClosed.get()); assertTrue(b.sinkClosed.get())
        assertEquals(size, b.written); assertTrue(b.ownsFile)
        assertTrue(a.largestRead.get() <= FrameTransport.CHUNK_BYTES)
        assertTrue(b.largestWrite.get() <= FrameTransport.CHUNK_BYTES)
        assertEquals(1, client.getOrThrow().receivedAttachments)
        assertEquals(1, a.acknowledgements); assertEquals(1, b.acknowledgements)
    }
    @Test fun `interrupted streamed file closes both sides and never publishes or acknowledges partial bytes`() {
        val (a, b) = devices(FrameTransport.CHUNK_BYTES + 10_000L); val (server, client) = exchange(a, b)
        assertTrue(server.isFailure); assertTrue(client.isFailure)
        assertTrue(a.sourceClosed.get()); assertTrue(b.sinkClosed.get()); assertFalse(b.ownsFile)
        assertEquals(FrameTransport.CHUNK_BYTES.toLong(), b.written)
        assertEquals(0, a.acknowledgements); assertEquals(0, b.acknowledgements)
    }
    @Test fun `shared verifier rejects overflow hash and truncation and cleans its target once`() = runBlocking {
        val bytes = byteArrayOf(1, 2, 3)
        val meta = AttachmentDto(UUID.randomUUID().toString(), "note", "image/png", bytes.size.toLong(), Hashing.sha256Hex(bytes))
        for (bad in listOf(byteArrayOf(1), byteArrayOf(9, 9, 9), byteArrayOf(1, 2, 3, 4))) {
            var published = false; var cleanup = 0
            val sink = VerifiedAttachmentSink(meta, ByteArrayOutputStream(), publish = { published = true }, cleanup = { cleanup++ })
            assertTrue(runCatching { sink.use { it.output.write(bad); it.commit() } }.isFailure)
            sink.close(); assertFalse(published); assertEquals(1, cleanup)
        }
        val empty = meta.copy(sizeBytes = 0, sha256 = Hashing.sha256Hex(ByteArray(0)))
        var committed = false
        VerifiedAttachmentSink(empty, ByteArrayOutputStream(), publish = { committed = true }).use { it.commit() }
        assertTrue(committed)
    }
}
